  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves the application, changing its status from PENDING to APPROVAL. Sends informational emails to both the customer and the company upon success.
   * Algorithm:
   *   1. Check if the application status equals PENDING. If not, return false.
   *   2. Check if the associated customer is eligible for IPO (customer.isEligibleForIPO() returns true). If not, return false.
   *   3. Set the application status to APPROVAL.
   *   4. Create two emails: one for the customer (with appropriate content) and one for the company.
   *   5. Add the emails to the application's emails list.
   *   6. Return true.
   * Related Features: status, customer, emails, Customer::isEligibleForIPO, Email::createEmailContent
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input: None
   * Output: boolean - true if the application is approved successfully, false otherwise.
   * Pre-condition: The application must be in PENDING status. The customer must be eligible for IPO.
   * Post-condition: If successful, the application status changes to APPROVAL. Two emails (customer and company) are created and added. If unsuccessful, the application status remains unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    // Check if the application status equals PENDING
    if (getStatus() != ApplicationStatus.PENDING) {
      return false;
    }
    
    // Check if the associated customer is eligible for IPO
    Customer customer = getCustomer();
    if (customer == null || !customer.isEligibleForIPO()) {
      return false;
    }
    
    // Set the application status to APPROVAL
    setStatus(ApplicationStatus.APPROVAL);
    
    // Create email for customer
    Company company = getCompany();
    String customerEmailContent = new Email().createEmailContent(company, getShare(), customer, getAmountOfMoney());
    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setContent(customerEmailContent);
    customerEmail.setReceiver(customer.getEmail());
    
    // Create email for company
    String companyEmailContent = new Email().createEmailContent(company, getShare(), customer, getAmountOfMoney());
    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setContent(companyEmailContent);
    companyEmail.setReceiver(company.getEmail());
    
    // Add the emails to the application's emails list
    getEmails().add(customerEmail);
    getEmails().add(companyEmail);
    
    return true;
  }

